const image = (name, alt, cls = '') => `<img class="${cls}" src="assets/${name}.webp" alt="${esc(alt)}" loading="lazy" width="700" height="480">`;
const list = items => `<ul class="company-checks">${items.map(item => `<li><span aria-hidden="true">✓</span>${esc(item)}</li>`).join('')}</ul>`;
const cta = () => `<section class="section container company-contact reveal"><div><p class="eyebrow"><span></span> LET’S TALK ALUMINIUM</p><h2>Discuss your<br>requirements with us.</h2><p>Connect with our team for product, material and fabrication guidance.</p></div><div><a class="button" href="contact.html">Get in Touch <span>↗</span></a><a class="company-contact-phone" href="tel:+919676910662">+91 96769 10662</a></div></section>`;
const relatedServices = current => `<section class="section panel"><div class="container"><div class="center-heading reveal"><p class="eyebrow"><span></span> OUR SERVICES</p><h2>Explore our capabilities</h2></div><div class="service-link-grid">${services.filter(service => service.slug !== current).map(service => `<a class="service-link-card reveal" href="capabilities.html#${service.slug}"><span data-icon="${service.slug === 'profile-design' ? 'profile' : 'tools'}" class="round-icon"></span><h3>${service.title}</h3><p>${service.subtitle}</p><span class="text-link">Explore Service ↗</span></a>`).join('')}</div></div></section>`;
const field = (label, name, type = 'text', required = false) => `<label>${label}${required ? ' *' : ''}<input name="${name}" type="${type}" ${required ? 'required' : ''} maxlength="150" ${name === 'email' ? 'autocomplete="email"' : name === 'name' ? 'autocomplete="name"' : name === 'phone' ? 'autocomplete="tel" pattern="[+0-9() .\\-]{7,25}"' : ''}></label>`;
function inquiry(kind, title, extra = '') {
  const career = kind === 'Career application';
  return `<form class="quote-form inquiry-form reveal" data-inquiry="${esc(kind)}"><h2>${title}</h2><p class="form-note">Prepare an email draft for our team. Nothing is sent until you send it in your email app.${career ? ' Attach your CV to that email before sending.' : ''}</p><div class="form-grid">${field('Full Name', 'name', 'text', true)}${field('Email Address', 'email', 'email', true)}${field('Phone Number', 'phone', 'tel', true)}${field('City', 'city')}${extra}</div><label>Message *<textarea name="message" required rows="5" maxlength="3000" placeholder="Tell us about your requirements..."></textarea></label><button class="button" type="submit">Prepare Email Inquiry <span>↗</span></button><p class="form-status" role="status" aria-live="polite"></p><a class="email-draft" hidden>Open email draft ↗</a></form>`;
}
function resumeForm(compact = false) {
  const details = compact
    ? field('Full name', 'name', 'text', true) + field('Your Email', 'email', 'email', true)
    : field('First name', 'first_name', 'text', true) + field('Last name', 'last_name', 'text', true) + field('Your Email', 'email', 'email', true) + field('Contact Number', 'phone', 'tel', true) + field('Experience', 'experience', 'text', true) + field('Current Company', 'current_company', 'text', true) + field('Current Gross P.M.', 'current_gross', 'text', true) + field('Notice Period', 'notice_period', 'text', true);
  const title = compact ? 'Upload Resume' : 'Apply & Upload Resume';
  const sum = compact ? '2 + 4' : '8 + 8';
  const answer = compact ? '6' : '16';
  return '<form class="quote-form inquiry-form reveal" data-inquiry="Career application"><h2>' + title + '</h2><p class="form-note">The original Extek form accepts PDF, DOC and DOCX files up to 2 MB. This static site prepares an email draft; attach the selected resume in your email app before sending.</p><div class="form-grid">' + details + '</div><label>Upload resume *<input name="resume" type="file" accept=".pdf,.doc,.docx,application/pdf,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document" required></label><label>Captcha: Solve this: ' + sum + ' =<input name="captcha" type="number" required min="' + answer + '" max="' + answer + '" inputmode="numeric"></label><button class="button" type="submit">Prepare Application Email <span>↗</span></button><p class="form-status" role="status" aria-live="polite"></p><a class="email-draft" hidden>Open application email ↗</a></form>';
}
