add('products', 'Our Aluminium Products', 'Precision products for diverse applications.', `<section class="section container"><div class="catalogue-heading reveal"><div><p class="eyebrow"><span></span> OUR PRODUCT RANGE</p><h2>Aluminium for your<br>next application.</h2><p>Explore lightweight products with design flexibility, strength, corrosion resistance and surface finishing possibilities. Contact our team for available specifications.</p></div><label>Browse by application<select data-product-filter><option value="all">All products</option>${[...new Set(products.map(product => product[3]))].map(category => `<option>${category}</option>`).join('')}</select></label></div><p data-product-count role="status" class="catalogue-count">${products.length} products</p><div class="product-grid catalogue-grid">${products.map(([id, title, img, category, heading, intro, subhead, detail, subhead2, detail2, subhead3, detail3, ctaText], i) => `<article class="product-card reveal" id="${id}" data-category="${category}">${img ? `<div class="product-image">${image(img, title)}</div>` : `<div class="product-illustration" aria-label="${title}"><span class="round-icon" data-icon="profile"></span><span>${title}</span></div>`}<div class="product-body"><span class="card-number">${String(i + 1).padStart(2, '0')} / ${category.toUpperCase()}</span><h3>${title}</h3><a class="text-link" href="${id}.html">View product details ↗</a><a class="text-link" href="contact.html?product=${encodeURIComponent(title)}">${ctaText || `Enquire About This Product ↗`}</a></div></article>`).join('')}</div></section>${cta()}`);

add('quality', 'Quality Assurance', 'Quality checks for aluminium materials, dimensions and finished products.', `<section class="section container company-story"><div class="reveal">${image('about-image-5585', 'Manufacturing professionals reviewing a component', 'detail-main-image')}</div><div class="company-copy reveal"><p class="eyebrow"><span></span> OUR APPROACH TO QUALITY</p><h2>Quality at every stage.</h2><p>At Extek Profiles Private Limited, quality assurance focuses on material quality, dimensional accuracy and product inspection to meet applicable specifications and customer requirements.</p><p>Our process covers incoming raw materials, in-process checks and finished products.</p></div></section><section class="section container quality-checks" id="quality-stages"><div class="center-heading reveal"><p class="eyebrow"><span></span> QUALITY ASSURANCE</p><h2>Checks at every stage<br>of production.</h2><p class="section-summary">Our quality process focuses on materials, dimensions and finished products, against applicable specifications and customer requirements.</p></div><div class="quality-stage-grid"><article class="quality-stage-card reveal" id="raw-material-inspection"><span class="quality-stage-number">01</span><h3>Raw Material Inspection</h3><p>Assess incoming aluminium materials against specified requirements before they proceed to manufacturing.</p></article><article class="quality-stage-card reveal" id="dimensional-accuracy"><span class="quality-stage-number">02</span><h3>Dimensional Accuracy Checks</h3><p>Verify profiles and components against required measurements, drawings and design specifications.</p></article><article class="quality-stage-card reveal" id="product-inspection"><span class="quality-stage-number">03</span><h3>Product Quality Inspection</h3><p>Inspect finished aluminium products for visible defects and check that they meet the specified requirements.</p></article><article class="quality-stage-card reveal" id="quality-testing"><span class="quality-stage-number">04</span><h3>Quality Testing</h3><p>Assess product characteristics against applicable specifications and relevant quality requirements.</p></article><article class="quality-stage-card reveal" id="certifications"><span class="quality-stage-number">05</span><h3>Certifications &amp; Standards</h3><p>Our certifications include ISO 9001:2015 for quality management, ISO 14001:2015 for environmental management, and ISO 45001:2018 for occupational health and safety.</p></article></div></section>${relatedServices()}${cta()}`);

