add('industries', 'Industries We Serve', 'Aluminium solutions for a wide range of businesses.', `<section class="section container"><div class="center-heading reveal"><p class="eyebrow"><span></span> DIVERSE APPLICATIONS</p><h2>One material.<br>Many industries.</h2><p class="section-summary">We supply industries and businesses with lightweight aluminium solutions, with components developed for the needs of each application.</p></div><div class="industry-grid full-industry-grid">${industries.map(([title,img,desc], i)=>`<article class="industry-card reveal" id="industry-${i+1}">${image(img,title)}<div><span>0${i+1} / INDUSTRIES</span><h3>${esc(title)}</h3><p>${desc}</p><a class="text-link" href="contact.html?product=${encodeURIComponent(title)}">Discuss Your Application ↗</a></div></article>`).join('')}</div></section>${cta()}`);

