add('sales-marketing', 'Sales & Marketing', 'Connect with our team about products and partnerships.', `<section class="section container business-form-layout"><div class="reveal"><p class="eyebrow"><span></span> PARTNERS & DEALERS</p><h2>Product knowledge.<br>Customer understanding.</h2><p>Our sales and marketing approach centres on understanding customer requirements and presenting the products and services that meet them, with quality and integrity.</p><p>We use sales management systems and marketing information to support efficient customer engagement. Partners and dealers can use the enquiry form to introduce their business.</p>${image('about-image-5585','Professionals discussing manufacturing requirements','business-image')}</div>${inquiry('Partner / dealer enquiry', 'Partners / Dealers',field('Company Name','company'))}</section>`,'company');

