add('careers', 'Careers at Extek', 'Be part of our manufacturing journey.', `<section class="section container company-story"><div class="reveal">${image('about-image-5585','Manufacturing professionals at work','detail-main-image')}</div><div class="company-copy reveal"><p class="eyebrow"><span></span> EXTEK PROFILES IS GROWING</p><h2>People at the heart<br>of our progress.</h2><p>We welcome people from different backgrounds and areas of expertise to support the growth of our aluminium manufacturing business.</p><p>Our employees are a vital resource. If you would like to join our journey, share your profile with the team.</p><a class="button" href="#career-application">Introduce Yourself <span>↗</span></a></div></section><section class="section panel"><div class="container"><div class="center-heading reveal"><p class="eyebrow"><span></span> EXPLORE OPPORTUNITIES</p><h2>Bring your skills<br>to our team.</h2><p class="section-summary">The company’s original careers page lists the roles below. Please contact the team to confirm current availability, qualifications and terms.</p></div><div class="job-list">${[['Aluminium Fabrication','Support fabrication of aluminium doors, windows and curtain walls in line with production schedules.'],['Business Development Manager','Discuss the business development opportunity and required experience with our team.'],['Aluminium Extrusion Production Manager','Support production operations, targets, quality improvement and coordination with engineering.']].map(([title,desc])=>`<details class="job-card reveal"><summary>${title}<span>+</span></summary><div><p>Telangana, India · Permanent, full time roles listed on the original site</p><p>${desc}</p><a class="text-link" href="careers.html?role=${encodeURIComponent(title)}#career-application">Enquire About This Role ↗</a></div></details>`).join('')}</div></div></section><section class="section container business-form-layout" id="career-application"><div class="reveal"><p class="eyebrow"><span></span> INTRODUCE YOURSELF</p><h2>Your next step<br>starts here.</h2><p>Send your resume to <a href="mailto:info@extekprofiles.com">info@extekprofiles.com</a> or <a href="mailto:sales@extekprofiles.com">sales@extekprofiles.com</a>.</p><p>The form prepares an application email. Attach your CV in your email app before sending it.</p></div>${inquiry('Career application','Share Your Profile',field('Role of Interest','role'))}</section>`);

