add('our-clients', 'Our Clients', 'Industries and customers we support.', `<section class="section container company-proof-grid" aria-label="Industries and customers"><article class="company-proof-card"><p class="eyebrow"><span></span> OUR CLIENTS</p><h2>Industries we support.</h2><p>Extek Profiles serves customers in automotive, railway, heavy electrical, machinery manufacturing, power tools, motors and pumps. We work with customers to understand their specifications and application needs.</p><a class="text-link" href="industries.html">Explore the industries we serve ↗</a></article><article class="company-proof-card"><p class="eyebrow"><span></span> CUSTOMER APPROACH</p><h2>Solutions shaped around requirements.</h2><p>Our team discusses dimensions, application requirements and manufacturing needs with customers to help identify suitable aluminium profile and fabrication solutions.</p><a class="text-link" href="contact.html">Talk to our team ↗</a></article></section>${cta()}`, 'company');
add('our-team', 'Our Team', 'People supporting our aluminium manufacturing capabilities.', `<section class="section container company-proof-grid" aria-label="Our team"><article class="company-proof-card"><p class="eyebrow"><span></span> OUR TEAM</p><h2>People behind the profiles.</h2><p>Our team supports aluminium profile design, extrusion, cutting, fabrication and quality checks. We bring these capabilities together to help customers develop solutions around their product requirements.</p><a class="text-link" href="contact.html">Talk to our team ↗</a></article><article class="company-proof-card"><p class="eyebrow"><span></span> WORK WITH US</p><h2>Bring your skills to Extek.</h2><p>We welcome people with different skills and experience who are interested in supporting our manufacturing work.</p><a class="text-link" href="careers.html">Explore careers ↗</a></article></section>${cta()}`, 'company');

