const source = fs.readFileSync('index.html','utf8');
const head = source.slice(0,source.indexOf('<main id="main">'));
const footer = source.slice(source.indexOf('<footer>'));
for (const page of pages) {
  let chrome = head.replace(/<title>.*?<\/title>/,`<title>${esc(page.title)} | Extek Profiles</title>`)
    .replace(/<meta name="description" content="[^"]*">/,`<meta name="description" content="${esc(page.subtitle)} Explore Extek Profiles products, services and company information.">`)
  .replace('<body>', '<body class="inner-page">')
    .replace(/href="#home"/g, 'href="index.html"')
    .replace('class="active" href="index.html"','href="index.html"');
  chrome = chrome.replace(new RegExp(`href="${page.slug}\\.html"`), `class="active" aria-current="page" href="${page.slug}.html"`);
  const banner = page.referenceLogin ? '<main id="main">' : `<main id="main"><section class="about-hero page-banner" id="page-top"><img class="about-hero-image" src="assets/home-banner_1835.webp" alt="Industrial manufacturing floor featured by Extek Profiles" fetchpriority="high" width="1920" height="1080"><div class="container"><p class="eyebrow light"><span></span> EXTEK PROFILES PRIVATE LIMITED</p><h1>${esc(page.title)}</h1><p>${esc(page.subtitle)}</p><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="index.html">Home</a><span aria-hidden="true">/</span><span aria-current="page">${esc(page.title)}</span></nav></div></section>`;
  const end = footer.replace(/href="#home"/g,'href="#page-top"').replace(/href="index.html">Back to top/g,'href="#page-top">Back to top');
  fs.writeFileSync(`${page.slug}.html`,chrome+banner+page.body+'</main>\n'+end);
}
module.exports = pages.map(page => `${page.slug}.html`);
